p = "GAATCCGGA"
g = ""
def patternIndex(pattern: str, genome: str) -> list[int]:
    x = 0
    patternI = set()
    while x < (len(genome)-len(pattern))+1:
        if(genome[x:x+len(pattern)]) == pattern:
            patternI.add(x)
        x = x+1
    return patternI
    

print(patternIndex(p, g))